function isValidDate(s) {
  if (typeof s !== 'string' || s.length !== 10) {
    return false;
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    return false;
  }
  const month = Number(s.substring(5, 7));
  const day = Number(s.substring(8, 10));
  if (month < 1 || month > 12) {
    return false;
  }
  if (day < 1 || day > 31) {
    return false;
  }
  return true;
}
