    withSep = dollars.charAt(i) + withSep;
    count = count + 1;
    if (count % 3 === 0 && i > 0) {
      withSep = thousands + withSep;
    }
  }

  // Accounting style: refunds get parentheses instead of a minus sign.
  let out = symbol + (negative ? '(' : '') + withSep;
  if (cents !== '') {
    out = out + decimal + cents;
  }
  if (negative) {
    out = out + ')';
  }
  return out;
