export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('parseCsvLine: expects a string');
  }
  const fields = [];
  let current = '';
  let inQuotes = false;
  let i = 0;
  while (i < line.length) {
    const ch = line.charAt(i);
    if (inQuotes) {
      if (ch === '"') {
        // RFC 4180: "" inside a quoted field is a literal quote
        if (line.charAt(i + 1) === '"') {
          current = current + '"';
          i = i + 2;
          continue;
        }
        inQuotes = false;
        i = i + 1;
        continue;
      }
      current = current + ch;
      i = i + 1;
      continue;
    }
    if (ch === '"') {
      inQuotes = true;
      i = i + 1;
      continue;
    }
    if (ch === ',') {
      fields.push(current);
      current = '';
      i = i + 1;
      continue;
    }
    current = current + ch;
    i = i + 1;
  }
  // A quote that never closes is almost always a broken Excel export (#1149)
  if (inQuotes) {
    throw new Error('parseCsvLine: unterminated quote in line: ' + line);
  }
  fields.push(current);
  return fields;
}

