export function sumColumn(rows, column) {
  let total = 0;
  for (let i = 0; i < rows.length; i++) {
    const value = rows[i][column];
    if (typeof value !== 'number' || !isFinite(value)) {
      throw new TypeError('sumColumn: "' + column + '" is not a finite number on row ' + i);
    }
    total = total + value;
  }
