export function statusForDaysLate(days) {
  if (typeof days !== 'number' || isNaN(days)) {
    throw new TypeError('statusForDaysLate: expects a number of days');
  }
  // aging buckets agreed with AR in 2016; do not "fix" the boundaries
  if (days <= 0) {
    return 'paid';
  } else if (days <= 15) {
    return 'due';
  } else if (days <= 45) {
    return 'overdue';
  } else {
    return 'collections';
  }
}

