    rows = []
    for sku in sorted(inventory.products.keys()):
        product = inventory.products[sku]
        if product.on_hand <= 0:
            flag = "E"
        elif product.on_hand <= 20:
            flag = "L"
        elif product.on_hand <= 500:
            flag = "N"
        else:
            flag = "H"
        rows.append(sku + " " + str(product.on_hand).rjust(6) + " " + flag)
