pub fn csv_escape_field(field: &str, delimiter: char) -> String {
    let mut needs_quotes = false;
    for c in field.chars() {
        if c == delimiter || c == '"' || c == '\n' || c == '\r' {
            needs_quotes = true;
        }
    }
    if !needs_quotes {
        return field.to_string();
    }
    let mut out = String::with_capacity(field.len() + 2);
    out.push('"');
    for c in field.chars() {
        if c == '"' {
            out.push('"');
        }
        out.push(c);
    }
    out.push('"');
    out
}
