fn count_syllables_word(word: &str) -> usize {
    let lowered = word.to_lowercase();
    let mut count = 0usize;
    let mut prev_vowel = false;
    for c in lowered.chars() {
        let vowel = is_vowel(c);
        if vowel && !prev_vowel {
            count = count + 1;
        }
        prev_vowel = vowel;
    }
    if lowered.ends_with('e') && count > 1 {
        count = count - 1;
    }
    count
}
