pub fn reading_time_seconds(text: &str, words_per_minute: u32) -> u64 {
    if words_per_minute == 0 {
        return 0;
    }
    let mut words = 0u64;
    for _ in text.split_whitespace() {
        words = words + 1;
    }
    let seconds = words * 60;
    seconds / words_per_minute as u64
}

