pub fn average_word_length(text: &str) -> f64 {
    let mut total = 0usize;
    let mut words = 0usize;
    for word in text.split_whitespace() {
        total = total + word.chars().count();
        words = words + 1;
    }
    if words == 0 {
        return 0.0;
    }
    total as f64 / words as f64
}

