        if !c.is_alphanumeric() {
            continue;
        }
        match counts.get_mut(&c) {
            Some(entry) => *entry = *entry + 1,
            None => {
                counts.insert(c, 1);
            }
        };
    }
    let mut items: Vec<(char, usize)> = counts.into_iter().collect();
    items.sort_by(|a, b| {
        if a.1 != b.1 {
